def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    me = tuple(h[0] for h in history)
    op = tuple(h[1] for h in history)

    opp_d = 0
    my_d = 0
    my_score = 0
    opp_score = 0
    for a, b in history:
        if b == 'D':
            opp_d += 1
        if a == 'D':
            my_d += 1

        if a == 'C':
            if b == 'C':
                my_score += 3
                opp_score += 3
            else:
                opp_score += 5
        else:
            if b == 'C':
                my_score += 5
            else:
                my_score += 1
                opp_score += 1

    opp_c = n - opp_d

    if n >= 99:
        return 'D'

    punished = 0
    forgiven = 0
    for i in range(n - 1):
        if me[i] == 'D':
            if op[i + 1] == 'D':
                punished += 1
            else:
                forgiven += 1

    start = n - 12 if n > 12 else 0
    recent_c = 0
    for x in op[start:]:
        if x == 'C':
            recent_c += 1

    last_me, last_opp = history[-1]
    behind = opp_score - my_score

    if opp_c == n:
        if my_d > 0:
            return 'D'
        return 'C'

    if opp_d * 10 <= n:
        if last_opp == 'D':
            if my_d > opp_d + 2 and recent_c >= 8:
                return 'C'
            return 'D'

        if forgiven >= 2 and forgiven > punished and my_d >= 2 and recent_c >= 9:
            return 'D'

        if behind > 12 and opp_d * 5 < n:
            return 'D'

        return 'C'

    if opp_d >= opp_c + 3:
        if last_opp == 'C' and recent_c >= 9 and opp_c >= opp_d - 4 and behind < 12:
            return 'C'
        return 'D'

    if behind > 12 and opp_d >= opp_c - 2:
        return 'D'

    if forgiven >= 3 and forgiven > punished and opp_c >= opp_d:
        return 'D'

    if last_opp == 'D':
        if my_d > opp_d + 2 and opp_d * 2 < n:
            return 'C'
        return 'D'

    if my_d > opp_d + 2 and opp_d * 2 < n:
        return 'C'

    return 'C'
